import streamlit as st

LOGO_B64 = ""

def show():
    header_html = (
        '<div class="main-header">'
        '<img src="data:image/png;base64,' + LOGO_B64 + '" style="height:90px;width:auto;margin-bottom:0.8rem;">'
        '<h1>MEDIFACT</h1>'
        '<p style="color:#b0e8f0;font-size:0.95rem;letter-spacing:2px;">GenesIsCare &mdash; A&H HealthTech</p>'
        '<p style="color:#00BCD4;font-size:0.85rem;margin-top:0.3rem;">Plateforme d''Analyse des Donnees Biomedicales Multi-Sources</p>'
        '<p style="color:#888;font-size:0.78rem;">Sujet 20 &mdash; Healthcare Dataset Collection</p>'
        '</div>'
    )
    st.markdown(header_html, unsafe_allow_html=True)

    col1, col2, col3, col4 = st.columns(4)
    with col1:
        st.markdown("<div class='kpi-card'><div class='value'>7+</div><div class='label'>Modules d'Analyse</div></div>", unsafe_allow_html=True)
    with col2:
        st.markdown("<div class='kpi-card'><div class='value'>20+</div><div class='label'>Fonctionnalites</div></div>", unsafe_allow_html=True)
    with col3:
        st.markdown("<div class='kpi-card'><div class='value'>CSV</div><div class='label'>Formats supportes</div></div>", unsafe_allow_html=True)
    with col4:
        st.markdown("<div class='kpi-card'><div class='value'>100%</div><div class='label'>Interactif</div></div>", unsafe_allow_html=True)

    st.markdown("<br>", unsafe_allow_html=True)
    st.subheader("Workflow de la plateforme")
    cols = st.columns(5)
    steps = [
        ("1. Importation", "Chargez vos datasets CSV medicaux"),
        ("2. Exploration", "Statistiques descriptives et correlations"),
        ("3. Preprocessing", "Nettoyage et transformation des donnees"),
        ("4. Visualisation", "Graphiques interactifs Plotly et Matplotlib"),
        ("5. Exportation", "CSV, Excel, PNG, Rapport complet"),
    ]
    for col, (title, desc) in zip(cols, steps):
        with col:
            st.markdown(
                "<div class='feature-card' style='text-align:center;'>"
                + "<b style='color:#00BCD4;'>" + title + "</b>"
                + "<p style='color:#b0e8f0;font-size:0.8rem;margin:0;'>" + desc + "</p>"
                + "</div>",
                unsafe_allow_html=True
            )

    st.markdown("<br>", unsafe_allow_html=True)
    st.subheader("Datasets Biomédicaux Multi-Sources Supportes")
    datasets = {
        "Diabete (Pima Indians)": "Analyse des facteurs de risque du diabete",
        "Maladies Cardiaques": "Heart Disease Dataset — prediction cardiovasculaire",
        "Cancer du Sein": "Breast Cancer Wisconsin — classification tumorale",
        "Maladies Renales": "Chronic Kidney Disease — insuffisance renale",
        "COVID-19": "Donnees cliniques COVID-19",
        "Sante Mentale": "Mental Health Dataset",
        "Sommeil et Sante": "Sleep Health Dataset",
        "Urgences": "Emergency Room Dataset",
        "Vaccination": "COVID Vaccination Dataset",
        "Laboratoire": "Medical Laboratory Dataset",
    }
    col1, col2 = st.columns(2)
    items = list(datasets.items())
    for i, (name, desc) in enumerate(items):
        with col1 if i % 2 == 0 else col2:
            st.markdown(
                "<div class='feature-card'>"
                + "<b style='color:#00BCD4;'>" + name + "</b>"
                + "<p style='color:#b0e8f0;font-size:0.85rem;margin:0;'>" + desc + "</p>"
                + "</div>",
                unsafe_allow_html=True
            )

    st.markdown("<br>", unsafe_allow_html=True)
    st.info("Commencez par **Importation des donnees** dans la barre de navigation pour charger votre dataset.")
